  type: 'UPDATE_INDEX_SETTINGS',
  target: { appId: 'MY_APP_ID', index: 'products' },
  validFor: '3600s',
  title: 'Rank in stock products first',
  description: 'Adds inStock to the custom ranking.',
  payload: { settings: { customRanking: ['desc(inStock)'] } },
  metadata: { origin: 'assist' },
  creation: { createdBy: '42', source: 'ASSIST' },
});

customGet.requestOptions should be escaped too:
const response = await client.customGet(
  { path: 'test/all', parameters: { query: 'to be overridden' } },
  {
    queryParameters: { query: 'parameters with space', 'and an array': ['array', 'with spaces'] },
    headers: { 'x-header-1': 'spaces are left alone' },
  },
);

customPost.allow post method for a custom path with:
const response = await client.customPost({
  path: 'test/all',
  parameters: { query: 'parameters' },
  body: { body: 'parameters' },
});

customPost.requestOptions can override default quer:
const response = await client.customPost(
  { path: 'test/requestOptions', parameters: { query: 'parameters' }, body: { facet: 'filters' } },
  {
    queryParameters: { query: 'myQueryParameter' },
  },
);

customPost.requestOptions merges query parameters w:
const response = await client.customPost(
  { path: 'test/requestOptions', parameters: { query: 'parameters' }, body: { facet: 'filters' } },
  {
    queryParameters: { query2: 'myQueryParameter' },
  },
);

customPost.requestOptions can override default head:
const response = await client.customPost(
  { path: 'test/requestOptions', parameters: { query: 'parameters' }, body: { facet: 'filters' } },
  {
    headers: { 'x-algolia-api-key': 'ALGOLIA_API_KEY' },
  },
);

